CREATE TABLE IF NOT EXISTS content_ideas (id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,pillar TEXT NOT NULL,hook TEXT,pain_point TEXT,value_proposition TEXT,cta TEXT,monetization TEXT,viral_score NUMERIC(5,2),audience_fit NUMERIC(5,2),save_score NUMERIC(5,2),share_score NUMERIC(5,2),commercial_intent NUMERIC(5,2),novelty NUMERIC(5,2),production_score NUMERIC(5,2),total_score NUMERIC(5,2),status TEXT NOT NULL DEFAULT 'IDEA',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reel_copy (id BIGSERIAL PRIMARY KEY,idea_id BIGINT REFERENCES content_ideas(id),provider TEXT NOT NULL,model TEXT NOT NULL,hook TEXT NOT NULL,problem TEXT NOT NULL,value TEXT NOT NULL,proof_or_example TEXT NOT NULL,cta TEXT NOT NULL,caption TEXT NOT NULL,hashtags JSONB NOT NULL,disclosure TEXT,input_tokens INTEGER DEFAULT 0,output_tokens INTEGER DEFAULT 0,estimated_cost_usd NUMERIC(12,6) DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
